// Java 8 added Collection.removeIf(Predicate) as a default method.
// Apache Commons SynchronizedCollection extended Collection, but did NOT override removeIf.
// When clients called removeIf on the synchronized collection, the default method ran WITHOUT locking!
import java.util.Collection;
import java.util.Objects;
import java.util.function.Predicate;

public interface LegacyCollection<E> {
    // Added in newer version as a default method:
    default boolean removeIf(Predicate<? super E> filter) {
        Objects.requireNonNull(filter);
        boolean result = false;
        // Iterates and modifies without synchronization!
        for (java.util.Iterator<E> each = iterator(); each.hasNext(); ) {
            if (filter.test(each.next())) {
                each.remove();
                result = true;
            }
        }
        return result;
    }
    java.util.Iterator<E> iterator();
}

