public class Main {
    public static void main(String[] args) {
        // A synchronized wrapper collection from Java 7 invoked removeIf in Java 8:
        // -> Concurrency failure / ConcurrentModificationException!
        // The default method had no idea the wrapper required a synchronized block!
    }
}

right_code.class:
// Safe practice: Test interfaces thoroughly with multiple implementations before shipping,
// and use default methods primarily to ease implementation of NEW interfaces, not to casually modify existing ones.
import java.util.function.Predicate;

public interface SafeCollection<E> {
    boolean removeIf(Predicate<? super E> filter);
}

// Synchronized implementations must explicitly synchronize:
public class SafeSynchronizedCollection<E> implements SafeCollection<E> {
    private final Object lock = new Object();

    @Override
    public boolean removeIf(Predicate<? super E> filter) {
        synchronized (lock) {
            // Safe synchronized execution guaranteed!
            return true;
        }
    }
}

right_code.call_site:
public class Main {
    public static void main(String[] args) {
        SafeSynchronizedCollection<String> col = new SafeSynchronizedCollection<>();
        col.removeIf(String::isEmpty); // Thread-safe and reliable
    }
}
